import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Bead, BeadBandInfo } from '../types'

const info = atom({ plugin: 'bead-band', key: 'info' } as const, null)

// Хост может не передать PATH из zsh — тогда bd ищется по пути Homebrew
const BD_CANDIDATES = ['bd', '/opt/homebrew/bin/bd']
const SOURCE_LABEL_PREFIX = 'src/'
const WORKTREE_BRANCH_PREFIX = 'bd-'
const TITLE_CHARS = 48
const RUN_TIMEOUT_MS = 10_000

type RawBead = { id?: unknown; title?: unknown; labels?: unknown }

const clip = (s: string, max: number) => (s.length > max ? s.slice(0, max - 1) + '…' : s)

async function runText($: EngineInterface, argv: string[]): Promise<string | null> {
  try {
    const r = await $.process.run(argv, { timeoutMs: RUN_TIMEOUT_MS })
    return r.exitCode === 0 ? r.stdout.trim() : null
  } catch {
    return null
  }
}

async function runBd($: EngineInterface, args: string[]): Promise<string | null> {
  for (const bd of BD_CANDIDATES) {
    const out = await runText($, [bd, ...args])
    if (out !== null) return out
  }
  return null
}

function toBead(raw: RawBead): Bead | null {
  if (typeof raw.id !== 'string' || typeof raw.title !== 'string') return null
  const labels = Array.isArray(raw.labels) ? raw.labels.filter((l): l is string => typeof l === 'string') : []
  const source = labels.find(l => l.startsWith(SOURCE_LABEL_PREFIX))
  return { id: raw.id, title: raw.title, source: source ? source.slice(SOURCE_LABEL_PREFIX.length) : null }
}

function parseBeads(json: string | null): Bead[] {
  if (!json) return []
  try {
    const parsed: unknown = JSON.parse(json)
    const list = Array.isArray(parsed) ? parsed : [parsed]
    return list.map(x => toBead((x ?? {}) as RawBead)).filter((b): b is Bead => b !== null)
  } catch {
    return []
  }
}

async function collect($: EngineInterface): Promise<BeadBandInfo> {
  const [toplevel, branch, inProgressJson] = await Promise.all([
    runText($, ['git', 'rev-parse', '--show-toplevel']),
    runText($, ['git', 'rev-parse', '--abbrev-ref', 'HEAD']),
    runBd($, ['list', '--status', 'in_progress', '--json', '--brief', '--readonly']),
  ])
  let beads = parseBeads(inProgressJson)

  // В воркчтри bd-<ID> его бид — главный, даже если он ещё не in_progress
  if (branch?.startsWith(WORKTREE_BRANCH_PREFIX)) {
    const ownId = branch.slice(WORKTREE_BRANCH_PREFIX.length)
    const own = beads.find(b => b.id === ownId) ?? parseBeads(await runBd($, ['show', ownId, '--json', '--readonly']))[0]
    if (own) beads = [own, ...beads.filter(b => b.id !== own.id)]
  }

  return { worktree: toplevel ? toplevel.split('/').pop() ?? null : null, branch, beads }
}

async function refresh($: EngineInterface) {
  const next = await collect($)
  await update($, info, () => next)
}

const FLIGHTDECK_PANE = 'flightdeck'

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    void refresh($)
    return result
  })

  // Бид или ветка могли смениться за ход — перечитываем в фоне
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    void refresh($)
    return result
  })

  // Строка задачи — первой строкой панели flightdeck: над полем ввода она теснила подсказки next-steps
  on('ui.render', { component: 'Pane', requestId: FLIGHTDECK_PANE }, async ($, e, next) => {
    const inner = await next(e)
    const data = await read($, info)
    if (!data || (!data.branch && data.beads.length === 0)) return inner

    const { Box, Text } = $.ui.resolve(e)
    const [main, ...rest] = data.beads
    const where = [data.worktree, data.branch].filter(Boolean).join(' · ')

    return (
      <Box flexDirection="column" alignItems="stretch" flexGrow={1}>
        <Box flexDirection="row" gap={1} minWidth={0}>
          {main ? (
            <>
              <Text color="claude">●</Text>
              <Text bold>{main.id}</Text>
              <Text wrap="truncate-end">{clip(main.title, TITLE_CHARS)}</Text>
            </>
          ) : (
            <Text dimColor>нет задачи в работе</Text>
          )}
          {main && rest.length > 0 ? <Text dimColor>+{rest.length}</Text> : null}
          {where ? <Text dimColor>{where}</Text> : null}
          {main ? (
            main.source ? (
              <Text dimColor>→ {main.source}</Text>
            ) : (
              <>
                <Text dimColor>→</Text>
                <Text color="warning">нет src/</Text>
              </>
            )
          ) : null}
        </Box>
        <Box>{inner}</Box>
      </Box>
    )
  })
}

