export type Bead = { id: string; title: string; source: string | null }

export type BeadBandInfo = {
  /** Имя рабочего дерева (папка корня репозитория) */
  worktree: string | null
  branch: string | null
  beads: Bead[]
}

declare module 'claude-code' {
  interface PluginState {
    'bead-band': { info: BeadBandInfo | null }
  }
}
